entries[22736] = { ["name"] = "Andonisus, der Seelenschlächter", ["text"] = "Stratholme\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nDauer: 5 min (Realzeit)Waffenhand Schwert\n184 - 343 Schaden Tempo 2.80\n(94.11 Schaden pro Sekunde)\nHaltbarkeit 130 / 130\nBenötigt Stufe 60\nAnlegen: Erhöht die Nahkampf- und Distanzangriffskraft um 600.\n\"Die Klinge scheint aus dieser Existenzebene zu verblassen. Es sieht aus, als sei sie nicht von dieser Welt.\"\nVerkaufspreis:" }
entries[22737] = { ["name"] = "Atiesh, Hohestab des Wächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 60\nBenutzen: Befreit Atiesh vom verderblichen Einfluss von Sargeras. Nur auf geheiligtem Boden zu benutzen. (15 Min Abklingzeit)\n\"Ein Wesen von großer Bösartigkeit ist in diesem Stab gefangen.\"" }
entries[22739] = { ["name"] = "Foliant der Verwandlung: Schildkröte", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt Verwandlung: Schildkröte.\nVerwandelt den Feind in eine harmlose Schildkröte und zwingt ihn, 50 Sek. lang so herumzuwandern. Während der Gegner in eine Schildkröte verwandelt ist, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden wandelt ihn in seine normale Gestalt zurück.\n\nEs kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren.\nVerkaufspreis:" }
