entries[22900] = { ["name"] = "Rezept: Elixier der Tarnung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(305)\nBenutzen: Lehrt euch, wie man ein Elixier der Tarnung herstellt.\nVerkaufspreis:\nElixier der Tarnung\nBenötigt Stufe 50\nBenutzen: Anwender kann 1 Stunde lang nicht aufgespürt werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe , Teufelsgras , Kristallphiole" }
