entries[22903] = { ["name"] = "Rezept: Trank der Wahnsinnsstärke", ["text"] = "Benötigt Alchemie\n(320)\nBenutzen: Lehrt Euch die Herstellung eines Tranks der Wahnsinnsstärke.\nVerkaufspreis:\nTrank der Wahnsinnsstärke\nBenötigt Stufe 50\nBenutzen: Erhöht Eure Stärke um 120 und verringert Euer Ausweichen um 75 . Hält 15 Sek. lang an. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen (3), Kristallphiole" }
entries[22904] = { ["name"] = "Rezept: Elixier des suchenden Auges", ["text"] = "Benötigt Alchemie\n(325)\nBenutzen: Lehrt Euch die Herstellung eines Elixiers des suchenden Auges.\nVerkaufspreis:\nElixier des suchenden Auges\nBenötigt Stufe 55\nBenutzen: Erhöht 10 Min. lang Eure Verstohlenheitsentdeckung. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe (2), Terozapfen , Kristallphiole" }
entries[22905] = { ["name"] = "Rezept: Elixier der erheblichen Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(330)\nBenötigt Ehrenfeste\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Elixiers der erheblichen Beweglichkeit.\nVerkaufspreis:\nElixier der erheblichen Beweglichkeit\nBenötigt Stufe 55\nBenutzen: Erhöht 1 Stunde lang die Beweglichkeit um 30 und den kritischen Trefferwert um 12 . Kampfelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Terozapfen , Teufelsgras (2), Kristallphiole" }
entries[22906] = { ["name"] = "Rezept: Verschleierungstrank", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(335)\nBenötigt Sporeggar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Verschleierungstranks.\n\nVerschleierungstrank\nBenötigt Stufe 55\nBenutzen: Verschleiert Euch gegenüber nahen Feinden, sodass Ihr weniger bedrohlich erscheint. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zottelkappe (3), Netherblüte , Kristallphiole" }
entries[22907] = { ["name"] = "Rezept: Erstklassiger Manatrank", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(340)\nBenutzen: Lehrt Euch die Herstellung eines erstklassigen Manatranks.\nVerkaufspreis:\nErstklassiger Manatrank\nBenötigt Stufe 55\nBenutzen: Stellt 2400 Mana wieder her. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Traumwinde (2), Teufelsgras , Kristallphiole" }
