entries[22911] = { ["name"] = "Rezept: Erheblicher Trank des traumlosen Schlafs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(350)\nBenutzen: Lehrt Euch die Herstellung eines erheblichen Tranks des traumlosen Schlafs.\nVerkaufspreis:\nErheblicher Trank des traumlosen Schlafs\nBenötigt Stufe 60\nBenutzen: Versetzt den Anwender 12 Sek. lang in einen traumlosen Schlaf. Während dieser Zeit regeneriert der Anwender ( 900 * 4) Gesundheit und ( 900 * 4) Mana. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Traumwinde , Alptraumranke , Kristallphiole" }
