entries[23060] = { ["name"] = "Ring der Knochensense", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+20 Stärke\n+20 Beweglichkeit\n+10 Ausdauer\nErhöht Eure Trefferwertung um + 10.\nKlassen: Schurke\nBenötigt Stufe 60\n\nRüstung der Knochensense (0/9)\nArmschienen der Knochensense\nBrustplatte der Knochensense\nStulpen der Knochensense\nHelm der Knochensense\nBeinplatten der Knochensense\nSchulterstücke der Knochensense\nSabatons der Knochensense\nTaillenschutz der Knochensense\nRing der Knochensense\n(2) Set : Eure normalen Nahkampfangriffe haben eine Chance, Euch zu stärken, und heilen Euch um 90 bis 110.\n(4) Set : Kritische Treffer mit Euren Fähigkeiten 'Meucheln', 'Finsterer Stoß' und 'Blutsturz' stellen 5 Energie wieder her.\n(6) Set : Verringert die von Euren Fähigkeiten 'Meucheln', 'Finsterer Stoß', 'Blutsturz' und 'Ausweiden' verursachte Bedrohung.\n(8) Set : Eure Fähigkeit 'Ausweiden' hat pro Combopunkt eine Chance, eine Schwachstelle in der Rüstung Eures Gegners aufzudecken, wodurch die nächste Anwendung Eurer Fähigkeiten 'Meucheln', 'Finsterer Stoß' oder 'Blutsturz' eine kritische Trefferchance von 100% erhält.\nVerkaufspreis:" }
entries[23061] = { ["name"] = "Ring des Glaubens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+24 Ausdauer\n+25 Intelligenz\n+16 Willenskraft\nKlassen: Priester\nBenötigt Stufe 60\n\nGewänder des Glaubens (0/9)\nGürtel des Glaubens\nBindungen des Glaubens\nReif des Glaubens\nHandschuhe des Glaubens\nGamaschen des Glaubens\nRobe des Glaubens\nSandalen des Glaubens\nSchulterpolster des Glaubens\nRing des Glaubens\n(2) Set : Verringert die Manakosten Eures Zaubers 'Erneuerung' um 12%.\n(4) Set : Bei kritischen Treffern Eures Zaubers 'Große Heilung' erhält Euer Ziel eine 'Rüstung des Glaubens', welche bis zu 500 Schaden absorbiert.\n(6) Set : Verringert die durch Eure Heilzauber verursachte Bedrohung.\n(8) Set : Jeder gewirkte Zauber kann den Effekt 'Offenbarung' auslösen, der Eure Willenskraft 30 Sek. lang um 60 erhöht. (Procchance: 5%)\nVerkaufspreis:" }
