entries[23618] = { ["name"] = "Pläne: Adamantitwetzstein", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (350)\nBenötigt Expedition des Cenarius\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Adamantitwetzsteins.\nVerkaufspreis:\nAdamantitwetzstein\nBenötigt Stufe 60\nBenutzen: Schärft Eure Klingenwaffe und erhöht so 1 Stunde lang den Waffenschaden um 12 und den kritischen Trefferwert um 0 . Kann nicht auf Gegenstände über Stufe 200 angewandt werden.\nVerkaufspreis:\nBenötigt Adamantitbarren , Erdpartikel (2)" }
entries[23619] = { ["name"] = "Pläne: Teufelsstahlschildstachel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (360)\nBenötigt Ehrenfeste\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Teufelsstahlschildstachels.\nVerkaufspreis:\nTeufelsstahlschildstachel\nBenutzen: Bringt einen Teufelsstahlstachel an Eurem Schild an, der bei jedem Blocken 26-38 Schaden verursacht.\nVerkaufspreis:\nBenötigt Teufelsstahlbarren (4), Urfeuer (4), Urerde (4)" }
